/* speculative score starter */

// Effects chain
const reverb = new Tone.Reverb(3).toDestination();
const distortion = new Tone.Distortion(0.2).toDestination();

// Kick Drum (four-on-the-floor)
const kick = new Tone.MembraneSynth({
  pitchDecay: 0.04,
  octaves: 6,
  oscillator: { type: "sine" },
  envelope: { attack: 0.001, decay: 0.5, sustain: 0.01, release: 0.1 }
}).connect(distortion);
const kickPattern = new Tone.Sequence((time, note) => {
  kick.triggerAttackRelease(note, "8n", time);
}, ["C1", "C1", "C1", "C1"], "4n");

// Shaker (constant 16ths)
const shaker = new Tone.NoiseSynth({
  noise: { type: 'white' },
  envelope: { attack: 0.005, decay: 0.05, sustain: 0 }
}).toDestination();
shaker.volume.value = -20;
const shakerPattern = new Tone.Loop(time => {
    shaker.triggerAttack(time);
}, "16n");

// Metallic Percussion
const clank = new Tone.MetalSynth({
    frequency: 200, harmonicity: 4.2, modulationIndex: 15, 
    envelope: { attack: 0.01, decay: 0.2, release: 0.1 },
    volume: -15
}).connect(reverb);
const clankPattern = new Tone.Sequence((time, note) => {
  clank.triggerAttack(time);
}, [null, null, 'A#4', null, null, null, 'A#4', null, null, 'A#4', null, null, null, 'A#4', null, null], '16n');

/* Speculative Score Draft */

// Set the tempo
Tone.Transport.bpm.value = 172;

// The bass instrument is an FMSynth, perfect for punchy, pitched sounds.
const subKickBass = new Tone.FMSynth({
  harmonicity: 3,
  modulationIndex: 12,
  envelope: {
    attack: 0.001,
    decay: 0.25,
    sustain: 0,
    release: 0.1
  },
  modulationEnvelope: {
    attack: 0.01,
    decay: 0.3,
    sustain: 0,
    release: 0.1
  }
}).toDestination();

// A filter chain to shape the tone: a lowpass to keep it dark and an EQ for a slight boost.
const filter = new Tone.Filter(400, 'lowpass').connect(subKickBass);

// A sequence to play the four-on-the-floor pattern.
// The pattern shifts notes very slowly; this example shows a two-bar change from D# to G#.
const bassPattern = new Tone.Sequence((time, note) => {
  subKickBass.triggerAttackRelease(note, '8n', time);
}, ['D#2', 'D#2', 'D#2', 'D#2', 'G#1', 'G#1', 'G#1', 'G#1'], '4n');

// Start the transport to hear the loop.
bassPattern.start(0);
Tone.Transport.start();
